const items = $input.all();
const ALLOWED = ['qualified', 'disqualified', 'review'];

function getErrorMessage(j) {
  const err = j.error;
  if (!err) return null;
  if (typeof err === 'string') return err;
  if (typeof err.message === 'string') return err.message;

  try {
    return JSON.stringify(err);
  } catch {
    return 'AI request failed';
  }
}

return items.map((item, index) => {
  const response = item.json || {};

  let original = {};
  let linkError = null;

  try {
    original = $('Check Fetch Evidence Usable').itemMatching(index).json || {};
  } catch (e) {
    linkError = 'Could not recover the original lead through item linking';
  }

  let parsed = null;
  let aiError = getErrorMessage(response);

  if (aiError) {
    aiError = 'AI request failed: ' + aiError;
  } else {
    const content =
      response.choices?.[0]?.message?.content;

    if (typeof content !== 'string' || !content.trim()) {
      aiError = 'AI response missing message content';
    } else {
      try {
        const cleaned = content
          .replace(/^```(?:json)?\s*/i, '')
          .replace(/\s*```$/, '')
          .trim();

        parsed = JSON.parse(cleaned);
      } catch {
        aiError = 'AI response was not valid JSON';
      }
    }
  }

  let score = null;
  let decision = 'review';
  let reasons = ['AI qualification unavailable'];

  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
    if (
      typeof parsed.score === 'number' &&
      Number.isFinite(parsed.score) &&
      parsed.score >= 0 &&
      parsed.score <= 100
    ) {
      score = parsed.score;
    } else {
      aiError = aiError || 'AI response had a missing or invalid score';
    }

    if (ALLOWED.includes(parsed.decision)) {
      decision = parsed.decision;
    } else {
      aiError = aiError || 'AI response had an invalid decision';
    }

    if (Array.isArray(parsed.reasons) && parsed.reasons.length > 0) {
      reasons = parsed.reasons.map(String);
    } else {
      aiError = aiError || 'AI response missing reasons';
      reasons = [aiError];
    }
  } else {
    aiError = aiError || 'AI response was not a valid JSON object';
  }

  if (aiError) {
    decision = 'review';
    score = null;
    reasons = [aiError, ...reasons.filter(r => r !== aiError)];
  }

  return {
    json: {
      ...original,
      ai_called: true,
      qualification_score: aiError ? null : score,
      decision,
      reasons,
      ai_error: aiError,
      ...(linkError ? { data_link_error: linkError } : {}),
    },
    pairedItem: { item: index },
  };
});

const items = $input.all();
const MAX_EXCERPT = 4000;

function toMessage(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (typeof value.message === 'string') return value.message;
  try {
    return JSON.stringify(value);
  } catch (e) {
    return String(value);
  }
}

// Convert raw HTML into more readable text.
function cleanHtml(html) {
  return html
    // Remove blocks that usually contain code or non-content.
    .replace(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style\s*>/gi, ' ')
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript\s*>/gi, ' ')
    .replace(/<svg\b[^>]*>[\s\S]*?<\/svg\s*>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')

    // Add boundaries around common block elements.
    .replace(/<\/(p|div|section|article|main|header|footer|nav|h[1-6]|li|tr|br|hr)\s*>/gi, '\n')
    .replace(/<br\b[^>]*>/gi, '\n')

    // Remove remaining HTML tags.
    .replace(/<[^>]*>/g, ' ')

    // Decode common HTML entities.
    .replace(/&nbsp;|&#160;|&#xA0;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;|&#34;/gi, '"')
    .replace(/&apos;|&#39;|&#x27;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (match, code) => {
      const n = Number(code);
      return n > 0 && n <= 0x10FFFF
        ? String.fromCodePoint(n)
        : ' ';
    })
    .replace(/&#x([0-9a-f]+);/gi, (match, code) => {
      const n = parseInt(code, 16);
      return n > 0 && n <= 0x10FFFF
        ? String.fromCodePoint(n)
        : ' ';
    })

    // Normalize whitespace.
    .replace(/\r/g, '\n')
    .replace(/[ \t\f\v]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

return items.map((item) => {
  const j = item.json || {};
  const text = typeof j.website_text === 'string'
    ? j.website_text
    : '';

  const statusCode = typeof j.statusCode === 'number'
    ? j.statusCode
    : null;

  const errorMessage = toMessage(j.error);
  const detailMessage = toMessage(
    j.details && (j.details.message || j.details.errorCode)
  );
  const signal = (errorMessage + ' ' + detailMessage).toLowerCase();
  const lowerText = text.toLowerCase();

  let status;

  if (errorMessage) {
    status = signal.includes('timeout') ||
      signal.includes('etimedout')
      ? 'timeout'
      : 'error';
  } else if (statusCode === null) {
    status = 'error';
  } else if (statusCode < 200 || statusCode >= 300) {
    status = 'http_error';
  } else if (
  /<title[^>]*>[^<]*(captcha|access denied|verify you are human|security check)[^<]*<\/title>/i.test(text) ||
  /id=["'](captcha|challenge-form)["']/i.test(text) ||
  /class=["'][^"']*(captcha-container|cf-challenge)[^"']*["']/i.test(text)
) {
  status = 'captcha';
  } else if (text.trim().length < 50) {
    status = 'empty';
  } else {
    status = 'ok';
  }

  const cleanedText = cleanHtml(text);

  return {
    json: {
      ...j,
      website_fetch_status: status,
      website_http_status: statusCode,
      website_fetch_error: errorMessage || null,
      website_text_excerpt: cleanedText.slice(0, MAX_EXCERPT),
      website_text_length: cleanedText.length,
    },
  };
});

const items = $input.all();
const ALLOWED = ['qualified', 'disqualified', 'review'];

return items.map((item) => {
  const j = item.json || {};
  const excerpt = typeof j.website_text_excerpt === 'string' ? j.website_text_excerpt : '';
  const score = typeof j.qualification_score === 'number' ? j.qualification_score : null;

  return {
    json: {
      lead_id: j.lead_id ?? null,
      company_name: j.company_name ?? null,
      website: j.website ?? null,
      domain: j.domain ?? null,
      description: typeof j.description === 'string' ? j.description : '',
      source: j.source ?? null,
      source_query: j.source_query ?? null,
      source_url: j.source_url ?? null,
      source_title: j.source_title ?? null,
      source_position: j.source_position ?? null,
      website_fetch_status: j.website_fetch_status ?? 'unknown',
      website_http_status: j.website_http_status ?? null,
      website_fetch_error: j.website_fetch_error ?? null,
      website_text_length: typeof j.website_text_length === 'number' ? j.website_text_length : excerpt.length,
      website_text_excerpt: excerpt,
      evidence_summary: excerpt.slice(0, 200),
      ai_called: j.ai_called === true,
      decision: ALLOWED.includes(j.decision) ? j.decision : 'review',
      qualification_score: score,
      reasons: Array.isArray(j.reasons) ? j.reasons.map((reason) => String(reason)) : [],
      ai_error: j.ai_error ?? null,
      finalized_at: new Date().toISOString(),
    },
  };
});

const items = $input.all();
const seenDomains = new Set();
const output = [];

for (const item of items) {
  const results = item.json.organicResults || [];

  for (const result of results) {
    const website = result.url || "";
    const match = website.match(/^https?:\/\/([^/:?#]+)/i);

    if (!match) continue;

    const domain = match[1]
      .replace(/^www\./i, "")
      .toLowerCase();

    if (!domain || seenDomains.has(domain)) continue;
    seenDomains.add(domain);

    const title =
      result.websiteTitle || result.title || "";

    output.push({
      json: {
        company_name: title || domain,
        website,
        domain,
        description: result.description || "",
        source: "google_search",
        source_query: item.json.searchQuery?.term || "",
        source_url: website,
        source_title: result.title || title,
        source_position: result.position ?? null,
      },
    });
  }
}

if (output.length === 0) {
  return [{
    json: {
      diagnostic: true,
      inputCount: items.length,
      resultCounts: items.map(
        item => item.json.organicResults?.length ?? 0
      ),
      message: "No normalized records were produced."
    }
  }];
}

return output;
